// ============================ CALENDAR (studio — Google Calendar surface) ====================
// Near-1:1 Google Calendar as a Data surface. Auth is brought forward from Echo: lib/gcal shells to
// Echo's venv get_credentials() for a live access token (the operator's grant), then calls Calendar
// v3 REST directly. Reads land first (Slice 1); writes are operator-initiated (later slices). main
// maps payloads to view shapes via studio/calendar_view; the renderer draws. The token is in-memory
// only — never written or logged. Identity: this is the OPERATOR'S calendar (his Google account).
function gcalOpts() { return echoVenv || {}; }

ipcMain.handle('calendar:auth-status', async () => {
  try {
    // Prefer Echo's own status route (gives email + scopes); fall back to a token probe.
    if (echoHttp && echoHttp.base) {
      const headers = { Accept: 'application/json' };
      if (echoHttp.token) headers.Authorization = `Bearer ${echoHttp.token}`;
      const res = await fetch(`${echoHttp.base}/saga/google/auth/status`, { headers });
      if (res && res.ok) { const s = await res.json(); return { ok: true, connected: !!s.connected, email: s.email || null, scopes: s.scopes || [] }; }
    }
    return { ok: true, connected: gcal.isConnected(gcalOpts()), email: null, scopes: [] };
  } catch (e) { return { ok: false, error: e.message, connected: false }; }
});

// Kick Echo's one-time OAuth consent flow (opens the operator's browser; blocks ≤300s server-side).
ipcMain.handle('calendar:connect', async () => {
  try {
    if (!echoHttp || !echoHttp.base) return { ok: false, error: 'engine HTTP unavailable' };
    const headers = { Accept: 'application/json' };
    if (echoHttp.token) headers.Authorization = `Bearer ${echoHttp.token}`;
    const res = await fetch(`${echoHttp.base}/saga/google/auth/start`, { method: 'POST', headers });
    const body = await res.json().catch(() => null);
    if (!res.ok || !body || body.ok === false) return { ok: false, error: (body && body.error) || `connect failed (${res.status})` };
    gcal.getToken({ ...gcalOpts(), force: true });   // warm the in-mem token cache post-connect
    return { ok: true, email: body.email || null, scopes: body.scopes || [] };
  } catch (e) { console.error('[calendar] connect failed:', e.message); return { ok: false, error: e.message }; }
});

// Calendar list + color palette together (the surface keeps both; events reuse the colors).
ipcMain.handle('calendar:list-calendars', async () => {
  try {
    const calsRaw = await gcal.listCalendars(gcalOpts());
    let colorsRaw = null;
    try { colorsRaw = await gcal.colors(gcalOpts()); } catch { /* colors are optional */ }
    return { ok: true, calendars: calendarView.normalizeCalendarList(calsRaw), colors: calendarView.colorMap(colorsRaw) };
  } catch (e) { console.error('[calendar] list-calendars failed:', e.message); return { ok: false, error: e.message }; }
});

// Events across the selected calendars within [timeMin, timeMax]. `calendars` = [{id,color}]; we
// fetch each in parallel, inject the calendar color, merge + sort. Per-calendar failures are
// collected (errors[]) without sinking the whole request.
ipcMain.handle('calendar:events', async (_e, { calendars = [], timeMin, timeMax } = {}) => {
  try {
    if (!Array.isArray(calendars) || !calendars.length) return { ok: true, events: [], errors: [] };
    if (!gcal.isConnected(gcalOpts())) return { ok: false, error: 'Google not connected' };
    const errors = [];
    const lists = await Promise.all(calendars.map(async (c) => {
      try {
        const raw = await gcal.listEvents({ calendarId: c.id, timeMin, timeMax, maxResults: 2500 }, gcalOpts());
        return calendarView.normalizeEventList(raw, { calendarId: c.id, calColor: c.color || '' }).events;
      } catch (err) { errors.push({ calendarId: c.id, error: err.message }); return []; }
    }));
    const events = lists.flat().sort((a, b) => a.startMs - b.startMs || a.summary.localeCompare(b.summary));
    return { ok: true, events, errors };
  } catch (e) { console.error('[calendar] events failed:', e.message); return { ok: false, error: e.message }; }
});

// Event writes — OPERATOR-INITIATED only (their own workbench, their own calendar). `form` is the
// editor-form shape; calendar_view.toGoogleEvent builds the validated Calendar v3 body. NEVER auto.
ipcMain.handle('calendar:create-event', async (_e, { calendarId, form } = {}) => {
  try {
    if (!calendarId || !form) return { ok: false, error: 'calendar + form required' };
    if (!gcal.isConnected(gcalOpts())) return { ok: false, error: 'Google not connected' };
    const body = calendarView.toGoogleEvent(form, { timeZone: form.timeZone });
    const created = await gcal.createEvent(calendarId, body, gcalOpts());
    return { ok: true, id: created.id };
  } catch (e) { console.error('[calendar] create failed:', e.message); return { ok: false, error: e.message }; }
});

ipcMain.handle('calendar:update-event', async (_e, { calendarId, eventId, form } = {}) => {
  try {
    if (!calendarId || !eventId || !form) return { ok: false, error: 'calendar + event + form required' };
    if (!gcal.isConnected(gcalOpts())) return { ok: false, error: 'Google not connected' };
    const body = calendarView.toGoogleEvent(form, { timeZone: form.timeZone });
    const updated = await gcal.updateEvent(calendarId, eventId, body, gcalOpts());
    return { ok: true, id: updated.id };
  } catch (e) { console.error('[calendar] update failed:', e.message); return { ok: false, error: e.message }; }
});

ipcMain.handle('calendar:delete-event', async (_e, { calendarId, eventId } = {}) => {
  try {
    if (!calendarId || !eventId) return { ok: false, error: 'calendar + event required' };
    if (!gcal.isConnected(gcalOpts())) return { ok: false, error: 'Google not connected' };
    await gcal.deleteEvent(calendarId, eventId, gcalOpts());
    return { ok: true };
  } catch (e) { console.error('[calendar] delete failed:', e.message); return { ok: false, error: e.message }; }
});

// ============================ CANVAS (studio — saga canvas renderer) =========================
// Render Zoe's LIVE canvas. CRITICAL: the canvas lives IN-MEMORY in the engine (canvas_publisher
// _TABS/_BLOCKS + websocket fan-out); the engine serves it over GET /canvas (full snapshot). The
// tenant_rainey.canvas_blocks SQLite table is ONLY written by TENANT processes — Saga's MAIN engine
// (what we run) keeps canvas state in-memory, so db_query would never see live blocks. We read the
// snapshot over HTTP (same engine canvasEmit writes to → consistent) and map via canvas_view. No model.
// WHY the last snapshot failed — quiet degrade must not mean UNDIAGNOSABLE. The 2026-07-15 hardening
// (b85e9c7) silenced the per-tick log, which also silenced the cause: the canvas has been showing a bare
// "canvas snapshot unavailable" with nothing anywhere saying whether it's a 401, a timeout, or an
// unreachable socket. Record the reason, log it at most once a minute, and hand it to the renderer.
// MAIN-THREAD LAG, sampled continuously at negligible cost (perf_hooks histogram). A canvas fetch failure
// has two candidate causes that look identical from the outside — the request really failed, or the main
// thread was BLOCKED past the deadline and the abort/socket died while nothing could service it. Attaching
// the loop lag to the failure decides it on the spot instead of costing another reboot to find out. Both
// observed symptoms (ECONNRESET, then a timeout against a route that answers in 2ms) are consistent with a
// stall: while the loop is wedged the engine closes its idle keep-alive socket (uvicorn default 5s), and
// the app then writes to a dead socket or misses its own deadline the instant it comes back.
let _loopLag = null;
try {
  const { monitorEventLoopDelay } = require('perf_hooks');
  _loopLag = monitorEventLoopDelay({ resolution: 20 });
  _loopLag.enable();
} catch (e) { _loopLag = null; }
// STALL ATTRIBUTOR (2026-08-04, diagnostic — REMOVE once the culprit is fixed + confirmed). The lag
// monitor above says a stall HAPPENED but not WHICH lane blocked the loop. markActivity() stamps the
// currently-running heavy lane; a self-timing 1s probe (its OWN clock — it must NOT touch _loopLag, which
// _lagNote resets per-window) writes the active lane to a durable log the moment the loop is blocked, so
// the NEXT stall names its own cause without a reboot to catch it in the act.
let _mainThreadActivity = { label: 'idle', at: Date.now() };
function markActivity(label) {
  const a = _mainThreadActivity;
  const next = { label: label || 'idle', at: Date.now() };
  // Retain the lane that JUST went idle: a synchronous lane's finally runs in the SAME macrotask as
  // its block, so the 1s probe always wakes to "idle" and the lane is never named — the histogram's
  // dominant active="idle" blind spot. Stamping who went idle (and when) lets the probe attribute a
  // stall to the lane that was running during the blocked window. Consecutive idle marks carry the
  // stamp forward instead of wiping it.
  if (next.label === 'idle') {
    if (a.label !== 'idle') { next.prevLabel = a.label; next.prevStartAt = a.at; next.prevEndAt = next.at; }
    else { next.prevLabel = a.prevLabel; next.prevStartAt = a.prevStartAt; next.prevEndAt = a.prevEndAt; }
  }
  _mainThreadActivity = next;
}
function _activeNote() {
  const a = _mainThreadActivity;
  if (!a || a.label === 'idle') return '';
  return ` [active: "${a.label}" for ${Date.now() - a.at}ms]`;
}
function _lagNote() {
  if (!_loopLag) return '';
  const maxMs = Math.round(_loopLag.max / 1e6);
  const meanMs = Math.round(_loopLag.mean / 1e6);
  _loopLag.reset();                                  // per-window, so the number describes THIS failure
  if (!Number.isFinite(maxMs) || maxMs < 1000) return ` [main thread ok: lag max ${maxMs}ms]`;
  return ` [MAIN THREAD STALLED: lag max ${maxMs}ms, mean ${meanMs}ms — the network is not the problem]${_activeNote()}`;
}
try {
  const _attribPath = path.join(__dirname, 'data', 'stall_attrib.log');
  let _lastTick = Date.now(), _attribLast = 0;
  setInterval(() => {
    const now = Date.now();
    const drift = now - _lastTick - 1000;            // how far past the expected 1s the loop came back
    _lastTick = now;
    if (drift >= 1500 && now - _attribLast > 2000) {  // loop was blocked ~1.5s+ beyond schedule
      _attribLast = now;
      const a = _mainThreadActivity;
      let label = a.label, ranMs = now - a.at;
      // "idle" but a lane went idle DURING/at the end of the blocked window → that lane's sync block
      // is what wedged the loop; its finally just beat the probe to the slot. Name it.
      if (a.label === 'idle' && a.prevLabel && a.prevEndAt >= now - drift - 2000) {
        label = `idle (just-ended: ${a.prevLabel})`; ranMs = a.prevEndAt - a.prevStartAt;
      }
      const line = `${new Date(now).toISOString()}\tblocked~${drift}ms\tactive="${label}"\tran=${ranMs}ms\n`;
      try { require('fs').appendFile(_attribPath, line, () => {}); } catch {}
      try { console.warn(`[stall-attrib] main thread blocked ~${drift}ms — active: "${label}" (${ranMs}ms)`); } catch {}
    }
  }, 1000).unref?.();
} catch {}

// MAIN-THREAD LOAD GOVERNOR (Lucas 2026-07-24 — "the freezes are getting to where its hard to type in
// the chat ... we need to better balance the load"). The cloud-slot board (lib/board) reserves a CLOUD
// slot for the reply, but NOTHING reserved MAIN-THREAD time: heavy synchronous background work
// (doc-decomp on a large PDF, package builds, graph writes) blocks the event loop, so keystrokes and
// reply IPC stall even though a cloud slot is free — the measured symptom is a /canvas GET with an 8s
// deadline returning elapsed 13.5s (≈5s the loop was wedged). This gate is ORTHOGONAL to the board AND
// to the cloud-slot coexistence ruling (that governs which MODELS run concurrently; this governs the
// CPU/event loop): while Lucas is actively conversing, the heavy BACKGROUND driver ticks yield the main
// thread so typing stays responsive. They resume the instant there's a ~30s lull; idle (overnight) they
// run at full tilt — the balance, not a silence. Window overridable via ZOE_CONVO_ACTIVE_SEC.
const CONVO_ACTIVE_MS = (parseFloat(process.env.ZOE_CONVO_ACTIVE_SEC) || 30) * 1000;
function _conversationActive() { return Date.now() - lastUserTurnTs < CONVO_ACTIVE_MS; }
const _loadDeferLogAt = {};
function _logLoadDeferral(lane) {                       // audible (once / 5min per lane) so a yielded lane is greppable, never invisible
  const now = Date.now();
  if (now - (_loadDeferLogAt[lane] || 0) < 5 * 60 * 1000) return;
  _loadDeferLogAt[lane] = now;
  console.log(`[load] ${lane} yielded to live conversation — main-thread balance (typing stays responsive)`);
}

// BOOT GRACE — the cold-boot stutter (profiled 2026-07-26/27): a fresh boot after downtime accrues a
// catch-up backlog, and every heavy lane wants to run AT ONCE while the app + Echo are still warming
// (models loading, MCP attaching, first render). Their synchronous better-sqlite3 traffic (~25-30% of
// main-thread time, get+all) then BUNCHES into intermittent multi-second event-loop stalls — the freeze
// Lucas felt. No single villain; the trigger is the simultaneous cold-start surge. Hold the heavy
// catch-up lanes for the first BOOT_GRACE window so the app settles first, then they resume at full tilt.
// Steady-state behavior is unchanged (the grace is a one-time boot window). Overridable / disable-able
// via ZOE_BOOT_GRACE_SEC (0 = off).
const _bootAt = Date.now();
const BOOT_GRACE_MS = (parseFloat(process.env.ZOE_BOOT_GRACE_SEC) || 90) * 1000;
function _bootGraceActive() { return BOOT_GRACE_MS > 0 && (Date.now() - _bootAt) < BOOT_GRACE_MS; }
const _bootDeferLogged = {};
function _logBootDefer(lane) {
  if (_bootDeferLogged[lane]) return;
  _bootDeferLogged[lane] = true;
  console.log(`[boot-grace] ${lane} held for the first ${Math.round(BOOT_GRACE_MS / 1000)}s — letting the app + engine warm before catch-up churn`);
}

let _canvasSnapReason = null, _canvasSnapLoggedAt = 0;
function _canvasSnapFail(reason) {
  _canvasSnapReason = reason;
  const now = Date.now();
  if (now - _canvasSnapLoggedAt > 60000) { _canvasSnapLoggedAt = now; console.error(`[canvas] snapshot unavailable: ${reason}`); }
  return null;
}
async function canvasSnapshot() {
  if (!echoHttp || !echoHttp.base) return _canvasSnapFail('engine HTTP base not configured');
  const headers = { Accept: 'application/json' };
  if (echoHttp.token) headers.Authorization = `Bearer ${echoHttp.token}`;
  // Degrade QUIETLY instead of throwing: the renderer's 5s canvas poll (canvas.js:877) would otherwise log a
  // '[canvas] get-all failed' every tick during any TRANSIENT engine window (restart, MCP reconnect/backoff,
  // a brief non-2xx). Timeout so a hung socket can't wedge the poll; return null on any not-ok/unreachable so
  // callers surface "Waiting for the engine…" and retry on the next poll. (2026-07-15: the recurring "canvas
  // fetch error" — endpoint verified healthy; the noise was throw-on-any-non-ok + no timeout + no backoff.)
  // TWO STACKS, and Chromium's goes FIRST. Node's global fetch (undici) fails this GET from inside the app
  // in two shapes — ECONNRESET, and a hang that trips the abort — while the very same request from an
  // external process succeeds every time and the engine answers /canvas in ~2ms with ~30KB. Ruled out by
  // experiment: the route, the token, a proxy, payload size, the keep-alive boundary (polling at the app's
  // exact fixed 5000ms cadence against uvicorn's 5s idle timeout is clean externally), and the runtime
  // (Electron ships Node 24.16, the box runs 24.15). What is left is in-process state — a poisoned undici
  // pool, a blocked main thread, or both, since a stall poisons the pool. Electron's net.fetch runs on
  // Chromium's stack with an independent pool AND issues the request off the JS thread, so it leads; node
  // fetch is the fallback. A GET is idempotent — trying both is always safe.
  //
  // ELAPSED is reported on failure because a timeout has two very different causes: the request really hung,
  // or the MAIN THREAD was blocked past the deadline and the abort fired the moment it came back. If a "timed
  // out after 8s" ever carries an elapsed far larger than 8s, this is main-thread stall — a canvas symptom of
  // a bigger problem — not a network fault. Don't chase the socket in that case.
  const TIMEOUT_MS = 8000;
  const get = async (fetchImpl) => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => { try { ctrl.abort(); } catch (e) {} }, TIMEOUT_MS);
    const t0 = Date.now();
    try {
      const res = await fetchImpl(`${echoHttp.base}/canvas`, { headers, signal: ctrl.signal });
      if (!res) return { err: `no response from ${echoHttp.base}/canvas` };
      if (!res.ok) return { err: `HTTP ${res.status}${res.status === 401 ? ' — engine rejected the admin token' : ''}` };
      return { snap: await res.json() };
    } catch (e) {
      const code = (e.cause && e.cause.code) || e.code || '';
      const ms = Date.now() - t0;
      if (e.name === 'AbortError') return { err: `timed out after ${TIMEOUT_MS / 1000}s (elapsed ${ms}ms)`, code: 'TIMEOUT' };
      return { err: `${e.name}: ${e.message}${code ? ` (${code})` : ''} after ${ms}ms`, code };
    } finally { clearTimeout(timer); }
  };

  let netFetch = null; try { netFetch = require('electron').net.fetch; } catch (e) {}
  const first = netFetch ? await get(netFetch) : null;
  if (first && first.snap) { _canvasSnapReason = null; return first.snap; }
  const second = await get(fetch);
  if (second.snap) {
    if (first) console.warn(`[canvas] Electron net failed (${first.err}) — served via node fetch instead`);
    _canvasSnapReason = null;
    return second.snap;
  }
  return _canvasSnapFail((first ? `${first.err} [electron net]; ${second.err} [node fetch]` : second.err) + _lagNote());
}

ipcMain.handle('canvas:list-tabs', async (_e, opts = {}) => {
  try {
    if (!(await ensureEngine())) return { ok: false, error: 'Echo engine not connected' };
    const snap = await canvasSnapshot();
    if (!snap) return { ok: false, error: 'canvas snapshot unavailable' };
    let tabs = (Array.isArray(snap.tabs) ? snap.tabs : []).map(canvasView.normalizeTab);
    if (opts && opts.openOnly) tabs = tabs.filter(t => t.open);
    tabs.sort((a, b) => (b.openedAt || 0) - (a.openedAt || 0));   // newest first
    return { ok: true, tabs };
  } catch (e) { console.error('[canvas] list-tabs failed:', e.message); return { ok: false, error: e.message }; }
});

ipcMain.handle('canvas:get-tab', async (_e, { tabKey } = {}) => {
  try {
    if (!tabKey) return { ok: false, error: 'no tab key' };
    if (!(await ensureEngine())) return { ok: false, error: 'Echo engine not connected' };
    const snap = await canvasSnapshot();
    if (!snap) return { ok: false, error: 'canvas snapshot unavailable' };
    const tabRow = (Array.isArray(snap.tabs) ? snap.tabs : []).find(t => (t.tab_key || t.key) === tabKey);
    if (!tabRow) return { ok: false, error: 'tab not found' };
    const blocks = (snap.blocks_by_tab && Array.isArray(snap.blocks_by_tab[tabKey])) ? snap.blocks_by_tab[tabKey] : [];
    return { ok: true, tab: canvasView.normalizeTab(tabRow), stream: canvasView.normalizeStream(blocks) };
  } catch (e) { console.error('[canvas] get-tab failed:', e.message); return { ok: false, error: e.message }; }
});

// Whole canvas in one shot: every tab as a DOCUMENT (normalized block stream) + its board position.
// The movable object on the canvas is the DOCUMENT (a tab), with its blocks flowing inside it.
// Operator-saved coords win; un-positioned docs get a deterministic auto-slot. One /canvas fetch.
ipcMain.handle('canvas:get-all', async () => {
  try {
    if (!(await ensureEngine())) return { ok: false, error: 'Echo engine not connected' };
    const snap = await canvasSnapshot();
    if (!snap) return { ok: false, error: `canvas snapshot unavailable — ${_canvasSnapReason || 'reason unknown'}` };
    const tabs = (Array.isArray(snap.tabs) ? snap.tabs : []).map(canvasView.normalizeTab);
    let state = {}; try { state = canvasLayoutStore.getPositions(); } catch {}
    const placed = canvasLayout.autoPlace(tabs.map(t => t.key), state);
    const posBy = {}; for (const p of placed) posBy[p.blockId] = p;   // autoPlace's id field == the tab key here
    const bb = snap.blocks_by_tab || {};
    const docs = tabs.map(t => {
      const s = state[t.key] || {};
      return {
        tab: t,
        stream: canvasView.normalizeStream(Array.isArray(bb[t.key]) ? bb[t.key] : []),
        pos: posBy[t.key] || { x: 48, y: 48 },
        w: s.w || null, h: s.h || null, hidden: !!s.hidden, minimized: !!s.minimized,
      };
    });
    return { ok: true, docs };
  } catch (e) { console.error('[canvas] get-all failed:', e.message); return { ok: false, error: e.message }; }
});

// Freeform board — persist a drag (operator moves a DOCUMENT) + reset arrangement (one doc or all).
ipcMain.handle('canvas:set-doc-pos', async (_e, { tabKey, x, y } = {}) => {
  try {
    if (!tabKey) return { ok: false, error: 'tabKey required' };
    return { ok: true, pos: canvasLayoutStore.setPosition(tabKey, x, y) };
  } catch (e) { console.error('[canvas] set-doc-pos failed:', e.message); return { ok: false, error: e.message }; }
});

// Merge a UI-state patch for a document: size {w,h}, {hidden}, {minimized}, or position.
ipcMain.handle('canvas:update-doc', async (_e, { tabKey, patch } = {}) => {
  try {
    if (!tabKey) return { ok: false, error: 'tabKey required' };
    return { ok: true, state: canvasLayoutStore.update(tabKey, patch || {}) };
  } catch (e) { console.error('[canvas] update-doc failed:', e.message); return { ok: false, error: e.message }; }
});

ipcMain.handle('canvas:reset-layout', async (_e, { tabKey } = {}) => {
  try { return { ok: true, cleared: canvasLayoutStore.clear(tabKey || undefined) }; }
  catch (e) { console.error('[canvas] reset-layout failed:', e.message); return { ok: false, error: e.message }; }
});

// Drag-and-drop a file onto the canvas → a DOCUMENT object. Reuses the suite's existing extractor
// (lib/doc_extract: .docx via mammoth, .pdf via pdfjs, .md/.txt direct) with a utf8 fallback for
// other text types, then opens a DOC tab with the content and positions it at the drop point. These
// dropped docs live in the engine's in-memory canvas (ephemeral) — ideal for quick test population.
// Tabs this process has already opened on the engine — shared by the drop handler and the emit/upsert
// writers below (a re-drop clears its entry so the refreshed document re-opens). Declared here, above its
// first use, rather than beside the writers.
const _canvasTabsOpened = new Set();
const IMG_MIME = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', bmp: 'image/bmp', svg: 'image/svg+xml' };
// Media MIME maps (2026-08-04) — a dropped audio/video file becomes a playable canvas card. src is the
// on-disk file:// URL (NOT a base64 data URI — a video inlined as base64 would be enormous); Electron
// streams it from disk in the <audio>/<video> element.
const AUDIO_MIME = { mp3: 'audio/mpeg', m4a: 'audio/mp4', aac: 'audio/aac', wav: 'audio/wav', ogg: 'audio/ogg', oga: 'audio/ogg', flac: 'audio/flac', opus: 'audio/opus' };
const VIDEO_MIME = { mp4: 'video/mp4', m4v: 'video/mp4', webm: 'video/webm', ogv: 'video/ogg', mov: 'video/quicktime', mkv: 'video/x-matroska' };
// A dropped file's path → a REAL file:// URL (lib/file_ingest.pathToSrc, the exact inverse of the srcToPath
// the re-ingest poller uses). This used to be string concatenation, which silently produced a BROKEN url for
// any filename holding a URL-significant character — "July Poll #3 - Crosstab Report.pdf" rendered as a blank
// document because everything after '#' is a fragment.
const fileUrl = (p) => require('./lib/file_ingest').pathToSrc(p);
ipcMain.handle('canvas:drop-doc', async (_e, { path: filePath, x, y } = {}) => {
  try {
    if (!filePath) return { ok: false, error: 'no file path' };
    if (!(await ensureEngine())) return { ok: false, error: 'Echo engine not connected' };
    const fs = require('fs');
    const ext = path.extname(filePath).replace(/^\./, '').toLowerCase();
    const baseName = path.basename(filePath).replace(/\.[^.]+$/, '');
    let mode = 'DOC', blockType = 'paragraph', data = null, title = baseName.slice(0, 120) || 'document';

    if (IMG_MIME[ext]) {                                   // IMAGE → render as an actual image
      const b64 = fs.readFileSync(filePath).toString('base64');
      // `src` = inline data URI (the picture renders); `file` = the real path so the ingest poller
      // re-reads it via file_ingest → VISION OCR → surfaceDocCards → cards (a data URI can't be re-read).
      data = { src: `data:${IMG_MIME[ext]};base64,${b64}`, alt: baseName, file: fileUrl(filePath) };
      blockType = 'image'; mode = 'ILLUSTRATIVE';
    } else if (AUDIO_MIME[ext]) {                          // AUDIO → a playable audio card (streamed from disk)
      data = { src: fileUrl(filePath), mime: AUDIO_MIME[ext], title: baseName };
      blockType = 'audio'; mode = 'ILLUSTRATIVE';
    } else if (VIDEO_MIME[ext]) {                          // VIDEO → a playable video card (streamed from disk)
      data = { src: fileUrl(filePath), mime: VIDEO_MIME[ext], title: baseName };
      blockType = 'video'; mode = 'ILLUSTRATIVE';
    } else if (ext === 'pdf') {                            // PDF → embed the REAL document (Chromium PDF viewer)
      data = { src: fileUrl(filePath), alt: baseName };
      blockType = 'document_file';                          // 'pdf' is not a valid engine block type
    } else if (ext === 'csv' || ext === 'tsv') {           // SPREADSHEET (delimited) → table
      const tbl = require('./studio/sheet_view').csvToTable(fs.readFileSync(filePath, 'utf8'), ext === 'tsv' ? '\t' : ',');
      // src = the on-disk file → the ingest poller re-reads the FULL sheet (not the truncated display rows)
      // via file_ingest → doc_extract.extractSpreadsheet → markdown table → surfaceDocCards → cards.
      data = { headers: tbl.headers, rows: tbl.rows, caption: tbl.truncated ? `+${tbl.truncated} more rows` : null, src: fileUrl(filePath) };
      blockType = 'table';
    } else if (ext === 'xlsx' || ext === 'xlsm' || ext === 'xls') {   // EXCEL → table (first sheet)
      const ExcelJS = require('exceljs');
      const wb = new ExcelJS.Workbook();
      await wb.xlsx.readFile(filePath);
      const ws = wb.worksheets[0];
      const rows = [];
      if (ws) ws.eachRow((r) => rows.push((r.values || []).slice(1).map(v => (v == null ? '' : (typeof v === 'object' ? (v.text || v.result || v.hyperlink || JSON.stringify(v)) : v)))));
      const tbl = require('./studio/sheet_view').toTable(rows);
      data = { headers: tbl.headers, rows: tbl.rows, caption: ws ? `${ws.name}${tbl.truncated ? ` · +${tbl.truncated} more rows` : ''}` : null, src: fileUrl(filePath) };
      blockType = 'table';
    } else if (ext === 'html' || ext === 'htm') {          // HTML → rich HTML block (renderer sanitizes before paint)
      let raw = ''; try { raw = fs.readFileSync(filePath, 'utf8'); } catch {}
      if (!raw.trim()) return { ok: false, error: 'empty / unreadable .html' };
      // keep the <body> if present (drop <head>/scripts noise); the renderer's sanitizeHtml strips the rest
      const bodyM = raw.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
      data = { html: bodyM ? bodyM[1] : raw }; blockType = 'document_file';
    } else if (ext === 'docx') {                           // WORD → rich HTML (tables, emphasis, inline images)
      try { const r = await require('./lib/doc_extract').extractDocxHtml(filePath); if (r && r.html && r.html.trim()) { data = { html: r.html }; blockType = 'document_file'; } } catch {}
      if (!data) {                                         // fallback: flattened markdown as a paragraph
        let markdown = ''; try { markdown = (await require('./lib/doc_extract').extractDocx(filePath)).markdown || ''; } catch {}
        if (!markdown.trim()) return { ok: false, error: 'empty / unreadable .docx' };
        data = { markdown, src: fileUrl(filePath) };   // full; rendered in progressive chunks below
      }
    } else {                                               // DOCUMENT (md/txt/code/pdf-text-fallback/…) → markdown
      let markdown = '';
      try { markdown = (await require('./lib/doc_extract').extractToMarkdown(filePath)).markdown || ''; }
      catch (e) { try { markdown = fs.readFileSync(filePath, 'utf8'); } catch { return { ok: false, error: `could not read ${path.basename(filePath)}: ${e.message}` }; } }
      if (!markdown.trim()) return { ok: false, error: 'empty / unreadable document' };
      const firstH = markdown.split(/\r?\n/).map(l => l.trim()).find(l => /^#{1,6}\s+\S/.test(l));
      if (firstH) title = firstH.replace(/^#{1,6}\s+/, '').slice(0, 120);
      data = { markdown, src: fileUrl(filePath) };   // full; rendered in progressive chunks below
    }

    // Tab key is derived from the FILE, not the clock. It used to end in Date.now(), so dropping the same
    // file twice made two separate documents — which is exactly what an operator does when a document didn't
    // render the first time, so the failure mode produced its own clutter. Keyed on the path, a re-drop
    // REFRESHES the document in place: close the old tab (dropping its blocks), forget the mirrored copy,
    // and rebuild from the file as it is now.
    const pathHash = require('crypto').createHash('sha1').update(path.resolve(filePath).toLowerCase()).digest('hex').slice(0, 8);
    const tabKey = `drop-${path.basename(filePath).replace(/[^a-z0-9]+/gi, '-').toLowerCase().slice(0, 40)}-${pathHash}`;
    const callTool = pollCallTool();
    const docStore = require('./lib/canvas_docs');
    let redrop = false;
    try { redrop = docStore.all().some((d) => d.tabKey === tabKey); } catch (e) {}
    if (redrop) {
      try { await callTool('saga_canvas_close_tab', { tab_key: tabKey }); } catch (e) {}
      try { docStore.forget(tabKey); } catch (e) {}
      _canvasTabsOpened.delete(tabKey);
      // Let the ingest poller read it again — the file may have CHANGED since the last drop, and the
      // seen-set is keyed on the tab, which is now stable across drops.
      try {
        const seen = JSON.parse(db.getMeta('canvas.ingested_tabs') || '[]').filter((k) => k !== tabKey);
        db.setMeta('canvas.ingested_tabs', JSON.stringify(seen));
      } catch (e) {}
      console.log(`[canvas] re-drop of "${title}" — refreshing the existing document in place`);
    }
    await callTool('saga_canvas_open_tab', { mode, tab_key: tabKey, title });
    // A DROP MEANS SHOW ME THIS (2026-07-30, "documents still don't open on the canvas"): layout
    // state persists hidden-by-tabKey and re-drops reuse the tabKey by design — so a card hidden
    // once could NEVER appear again, however many times he dropped the file (measured: 57 of 60
    // layout rows hidden, all 45 drop tabs among them). Dropping is the operator's explicit
    // intent to see the document: force it visible.
    try { canvasLayoutStore.update(tabKey, { hidden: false, minimized: false }); } catch (e) { console.error('[canvas] unhide on drop failed:', e.message); }
    const PREVIEW_CHUNK = 40000;   // a large text doc renders one chunk at a time from the top so it never hangs
    if (blockType === 'paragraph' && data && typeof data.markdown === 'string' && data.markdown.length > PREVIEW_CHUNK) {
      // RECURSIVE BUILD (Lucas): split on line boundaries and add the FIRST chunk now (instant top-of-doc
      // preview), then stream the rest as blocks — the tab builds up as each finishes. Ingest is decoupled:
      // the poller re-reads the whole file via `src`, so background extraction stays full regardless.
      const parts = require('./lib/contact_extract').chunkForExtraction(data.markdown, { size: PREVIEW_CHUNK }).chunks;
      const first = { markdown: parts[0], src: data.src };
      const r0 = await callTool('saga_canvas_add_block', { tab_key: tabKey, block_type: 'paragraph', data: first });
      canvasMirror(tabKey, mode, title, (r0 && r0.block_id) || null, 'paragraph', first);
      (async () => {
        for (let i = 1; i < parts.length; i++) {
          try {
            const ri = await callTool('saga_canvas_add_block', { tab_key: tabKey, block_type: 'paragraph', data: { markdown: parts[i] } });
            canvasMirror(tabKey, mode, title, (ri && ri.block_id) || null, 'paragraph', { markdown: parts[i] });
          } catch (e) {}
          await new Promise(res => setTimeout(res, 80));   // yield so each chunk paints before the next
        }
        console.log(`[canvas] "${title}" built in ${parts.length} progressive chunks`);
      })().catch(() => {});
    } else {
      const r = await callTool('saga_canvas_add_block', { tab_key: tabKey, block_type: blockType, data });
      canvasMirror(tabKey, mode, title, (r && r.block_id) || null, blockType, data);
    }
    try { canvasLayoutStore.setPosition(tabKey, x, y); } catch {}
    return { ok: true, tabKey, title };
  } catch (e) { console.error('[canvas] drop-doc failed:', e.message); return { ok: false, error: e.message }; }
});

// ZOE CANVAS DRIVE (Slice 2) — the orchestrator's SINGLE seam for writing a professional-register
// block to Zoe's saga canvas (write path A: Side Quest calls saga_canvas_* directly through the Echo
// suit). Determinism law: content here is produced upstream by caged cloud leaves (organize/condense
// reasoner); Dans NEVER writes a block. Tab key is deterministic per focus so re-opens are idempotent
// and the tab re-attaches after a restart. Fully fail-safe: a canvas error never breaks the research
// loop (the deliverable FILES remain the durable artifact; the canvas is the live render).
// SWARM QUIETING (research-allocation S5): while a swarm is OUT, only the swarm's own threads ANNOUNCE
// themselves in CHAT — the operator asked to focus on the swarm, so the background rotation keeps
// RESEARCHING (its work still lands in the graph) but stops INTERRUPTING.
//
// CHAT ONLY — never the canvas (Lucas 2026-07-20). This gate used to sit in front of canvasEmit /
// canvasUpsertBlock too, and that was a category error: chat is an interruption the operator can be spared,
// but the canvas is the WORKSPACE he goes looking at. Muting it doesn't quiet anything — it silently throws
// her finished work away, including the boot rehydrate, so the canvas comes back blank and stays blank for
// as long as the swarm is out. A stuck `county-commissions-la` partition kept the canvas empty for 27 hours
// exactly this way; the only document that survived was one the operator dropped by hand (drop-doc never
// consulted this gate). Quiet the announcements, never the workspace.
function _surfaceAllowed(focusId) {
  try {
    const sw = JSON.parse(db.getMeta('sched.autonomic') || '{}').swarm;
    if (!sw) return true;                                   // no swarm → everything surfaces normally
    return db.getMeta(`focus.${focusId}.swarm`) === '1';    // swarm out → only swarm threads surface
  } catch { return true; }
}

// Write-through mirror of everything we put on the canvas → lib/canvas_docs, so boot can rebuild the board.
// Never throws and never blocks the write it follows: a mirror failure must not cost her the live block.
function canvasMirror(tabKey, mode, title, blockId, blockType, data) {
  if (!tabKey || !blockId) return;
  try {
    const store = require('./lib/canvas_docs');
    store.recordTab({ tabKey, mode, title });
    store.recordBlock({ tabKey, blockId, blockType, data: data || {} });
  } catch (e) { console.error('[canvas] mirror failed:', e.message); }
}

// AUTONOMIC-CANVAS GATE (Slice P — "I get a canvas doc every time she starts a new county, but never
// when I ask") — an autonomic county BEAT focus (origin 'beat') is MECHANICALLY directed but Lucas
// never asked for it, so it must NOT flood the workspace with a tab per county (the canvas_docs store
// had ~40 `directed-35xx` county tabs). Its research still lands in the graph + the deliverable FILE
// (the durable artifacts, per the CHAT-ONLY note above), so NOTHING is thrown away — only the live
// canvas render is withheld for beat runs. Numeric research focus ids only; meeting-*/promise-* tabs
// are non-numeric → never gated. A directed USER run (origin 'user'/unmarked) renders as before.
const _beatCanvasLogged = new Set();
function _canvasBeatGated(focusId) {
  try {
    if (!/^\d+$/.test(String(focusId))) return false;
    if (require('./lib/focus').originOf(focusId) !== 'beat') return false;
    if (!_beatCanvasLogged.has(String(focusId))) {
      _beatCanvasLogged.add(String(focusId));
      console.log(`[canvas] beat focus #${focusId} — canvas render suppressed (autonomic county work stays in graph+file, off the workspace)`);
    }
    return true;
  } catch { return false; }
}

async function canvasEmit({ focusId, title, tabMode, blockType, data }) {
  try {
    if (!blockType) return false;
    if (_canvasBeatGated(focusId)) return false;
    if (!(await ensureEngine())) return false;
    const ce = require('./studio/canvas_emit');
    const callTool = pollCallTool();
    const tabKey = ce.tabKeyForFocus(focusId);
    if (!_canvasTabsOpened.has(tabKey)) {
      await callTool('saga_canvas_open_tab', { mode: ce.mode(tabMode || 'RESEARCH'), tab_key: tabKey, title: ce.tabTitleForGoal(title) });
      _canvasTabsOpened.add(tabKey);
    }
    const r = await callTool('saga_canvas_add_block', { tab_key: tabKey, block_type: blockType, data: data || {} });
    canvasMirror(tabKey, ce.mode(tabMode || 'RESEARCH'), ce.tabTitleForGoal(title), (r && r.block_id) || null, blockType, data);
    return true;
  } catch (e) { console.error('[canvas] emit failed:', e.message); return false; }
}

// DELIVERY-PROMISE artifact (Slice P3, PLAN_MAP §2): a conversation promise materializes as its own
// doc-mode tab (tab_key promise-<slug>, stable across turns — later promises on the same topic land
// in the SAME tab). Separate from canvasEmit because there is no focus id: the promise is the anchor.
// ⭐ BUILD A REPORT FROM WHAT SHE ALREADY HOLDS (2026-08-07). The missing path behind "she refuses or
// stalls on the report": an explicit order routed to chat-answer surfaces instead of composing a
// document. This gathers the research docs she HOLDS on the topic, composes ONE report through the
// caged composer, SAVES it to notes/, and lands it on the canvas — an artifact, not a promise. If she
// genuinely holds nothing, it says so plainly (and does NOT fabricate a document).
// Execute an EXPLICIT canvas order (lib/canvas_command) and land the result DETERMINISTICALLY —
// the parish-list fix: "identify on a fresh canvas doc…" + "print to the canvas" produced zero
// canvas writes while the replier narrated success. One bounded INTERACTIVE-lane operator run
// produces the grounded content; promiseArtifactEmit lands it; the delivery claim is true by
// construction. A CANNOT: answer is relayed plainly — never a narrated success.
async function buildCanvasFromOrder({ io, channel, sessionId, order }) {
  const recent = (db.getRecentTurns(10) || []).filter((t) => t.speaker === 'user').sort((a, b) => (a.ts || 0) - (b.ts || 0)).slice(-4)
    .map((t) => `- ${String(t.content).slice(0, 300)}`).join('\n');
  let md = '';
  try {
    const res = await runCloudOperator({
      userMessage: `Lucas ordered content ONTO HIS CANVAS. His order: "${order}"\n\nHis recent messages (oldest first — they carry the subject when the order is a bare "print it"):\n${recent}\n\nProduce the EXACT markdown content the canvas doc should hold — nothing else, no preamble. Ground every entry via your tools (echo / localdb / recall / web as needed); NEVER invent entries. A bounded list (places, names, items) must be COMPLETE and one item per line, in the order he asked for. If you cannot ground the content, reply with ONE line starting "CANNOT:" naming what is missing.`,
      context: '', task: true,     // Lucas-directed → interactive lane; never quota-deferred
    });
    md = res && res.answer ? String(res.answer).trim() : '';
  } catch (e) { console.error('[canvas-cmd] execute failed:', e.message); }
  if (!md) {
    await fireToolFollowup({ io, channel, sessionId, resultText: `[Lucas ordered content onto his canvas ("${order.slice(0, 120)}") but the execution produced nothing. Say plainly that the canvas write did NOT happen and you'll retry on his word — never claim it landed.]` });
    return;
  }
  if (/^CANNOT:/i.test(md)) {
    await fireToolFollowup({ io, channel, sessionId, resultText: `[Lucas ordered content onto his canvas but it could not be grounded: "${md.slice(0, 200)}". Tell him exactly that — what is missing — and do NOT claim anything landed.]` });
    return;
  }
  const title = order.replace(/\b(?:please|can you|could you)\b/gi, '').replace(/\b(?:on|onto|to|into)\s+(?:a\s+fresh\s+|a\s+new\s+|a\s+|the\s+|my\s+|your\s+)?canvas(?:\s+doc(?:ument)?|\s+tab)?\b/gi, '').replace(/\s+/g, ' ').trim().slice(0, 60) || 'Canvas doc';
  const slug = `canvas-${title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'doc'}`;
  try { await promiseArtifactEmit({ slug, title, markdown: md }); } catch (e) {
    console.error('[canvas-cmd] emit failed:', e.message);
    await fireToolFollowup({ io, channel, sessionId, resultText: `[The canvas write FAILED (${e.message}). Tell Lucas plainly — the content is composed but did not land; never claim it is on the canvas.]` });
    return;
  }
  const lines = md.split('\n').filter((l) => l.trim()).length;
  _stampWorkingCanvasDoc({ slug, title, md });
  console.log(`[canvas-cmd] order executed → "${title}" landed on canvas (${md.length}ch, ${lines} line(s))`);
  await fireToolFollowup({ io, channel, sessionId, resultText: `[The canvas doc Lucas ordered IS LANDED — "${title}", ${lines} content line(s), on his Canvas now. Tell him it's there and what it holds in one sentence, and invite him to verify. Do NOT add extras he didn't ask for and do NOT offer follow-on work — he said slow, one step at a time.]` });
}

// The WORKING canvas doc — what "the document we're building" refers to. Stamped at every
// create/edit landing; the edit net only fires while this is fresh. The markdown is the edit
// executor's source of truth AND lands as a notes/ file so the product ledger can find the doc
// later ("pull up that parish list we made" must not miss a canvas-born product).
const WORKING_CANVAS_FRESH_MS = 2 * 3600 * 1000;
function _stampWorkingCanvasDoc({ slug, title, md }) {
  try {
    db.setMeta('canvas.working_slug', slug);
    db.setMeta('canvas.working_title', title);
    db.setMeta('canvas.working_md', String(md).slice(0, 60000));
    db.setMeta('canvas.working_at', String(Date.now()));
  } catch {}
  try { require('fs').writeFileSync(filesLib.resolvePath(`notes/canvas-${slug.replace(/^canvas-/, '')}.md`), `# ${title}\n\n${md}\n`, 'utf8'); } catch {}
}
function _workingCanvasFresh() {
  try { return !!db.getMeta('canvas.working_slug') && (Date.now() - parseInt(db.getMeta('canvas.working_at') || '0', 10)) < WORKING_CANVAS_FRESH_MS; } catch { return false; }
}

// COMPREHENSION FALLBACK for canvas edits (Lucas, 2026-08-07: "kimi can't read typos? this is
// worse than a regex block"). He is right about the architecture: the model reads "pullet the
// parish list" as "bullet…" effortlessly — but the regex ran BEFORE any model saw the message, and
// on a miss the turn fell to a replier with no canvas hands. While a working doc is fresh, the
// regex is only the zero-latency fast path; anything it misses gets ONE bounded classifier call —
// typo-tolerant by nature — whose yes routes into the same edit door. No session → no call.
function _validateEditIntent(raw) {
  try {
    const m = String(raw || '').match(/\{[\s\S]*\}/);
    if (!m) return { valid: false, error: 'no JSON object' };
    const o = JSON.parse(m[0]);
    if (typeof o.edit !== 'boolean') return { valid: false, error: 'missing boolean "edit"' };
    return { valid: true, value: { edit: o.edit, instruction: String(o.instruction || '').slice(0, 300) } };
  } catch (e) { return { valid: false, error: e.message }; }
}
async function _classifyCanvasEditIntent(userMessage) {
  try {
    const title = db.getMeta('canvas.working_title') || 'the working doc';
    const v = await require('./lib/cloud_logic').ask({
      task: 'canvas_edit_intent', v: 1,
      input: { workingDoc: title, message: String(userMessage || '').slice(0, 300) },
      want: `Lucas and the assistant are building a canvas document step by step ("${title}"). Given his MESSAGE, decide: is it an instruction to modify, extend, reformat, or continue THAT document? Typos are common — read intent, not spelling ("pullet the list" means "bullet the list"). Conversation, questions about content, and unrelated asks are edit=false. Reply ONLY strict JSON: {"edit": true|false, "instruction": "<his instruction, normalized, typos corrected>"}.`,
      validate: _validateEditIntent, numPredict: 150, think: false,
    });
    if (v && v.edit && v.instruction) { console.log(`[canvas-cmd] classifier read the intent: "${v.instruction}"`); return { order: v.instruction }; }
    return null;
  } catch { return null; }   // fail-soft: no classifier → the fast path was the only path
}

// Apply an EDIT order to the working canvas doc: the current markdown + his instruction → the
// COMPLETE updated doc → re-emit on the SAME slug (updates in place) → re-stamp. Pure reformats
// need no tools; content additions get them — one bounded interactive-lane run covers both.
async function buildCanvasEditFromOrder({ io, channel, sessionId, order }) {
  const slug = db.getMeta('canvas.working_slug'), title = db.getMeta('canvas.working_title') || 'Canvas doc';
  const cur = db.getMeta('canvas.working_md') || '';
  if (!slug || !cur) {
    await fireToolFollowup({ io, channel, sessionId, resultText: `[Lucas gave a canvas edit order ("${order.slice(0, 120)}") but no working doc content is stored. Say plainly you've lost the working copy and ask him to name what to rebuild — never claim an edit landed.]` });
    return;
  }
  let md = '';
  try {
    const res = await runCloudOperator({
      userMessage: `Lucas is editing the canvas doc "${title}" step by step. CURRENT CONTENT:\n"""\n${cur}\n"""\n\nHIS EDIT INSTRUCTION: "${order}"\n\nOutput the COMPLETE updated markdown for the whole doc after applying EXACTLY this instruction — change nothing he did not ask to change, add nothing extra, keep every existing entry unless he asked for its removal. Ground any NEW factual entries via your tools (echo / localdb / recall / web); NEVER invent entries. If the instruction cannot be applied or grounded, reply with ONE line starting "CANNOT:" naming why.`,
      context: '', task: true,     // Lucas-directed → interactive lane; never quota-deferred
    });
    md = res && res.answer ? String(res.answer).trim() : '';
  } catch (e) { console.error('[canvas-cmd] edit execute failed:', e.message); }
  if (!md || /^CANNOT:/i.test(md)) {
    await fireToolFollowup({ io, channel, sessionId, resultText: `[Lucas's canvas edit did NOT apply${md ? `: "${md.slice(0, 200)}"` : ' (the edit run produced nothing)'}. Tell him exactly that — the doc on his canvas is UNCHANGED — and never claim the edit landed.]` });
    return;
  }
  try { await promiseArtifactEmit({ slug, title, markdown: md }); } catch (e) {
    console.error('[canvas-cmd] edit emit failed:', e.message);
    await fireToolFollowup({ io, channel, sessionId, resultText: `[The canvas update FAILED to land (${e.message}) — the doc on screen is UNCHANGED. Say so plainly.]` });
    return;
  }
  _stampWorkingCanvasDoc({ slug, title, md });
  const lines = md.split('\n').filter((l) => l.trim()).length;
  console.log(`[canvas-cmd] edit applied → "${title}" updated in place (${md.length}ch, ${lines} line(s))`);
  await fireToolFollowup({ io, channel, sessionId, resultText: `[The edit Lucas ordered IS APPLIED — "${title}" updated in place on his Canvas (${lines} line(s) now). Tell him in one sentence what changed and invite him to verify. No extras, no offers of next steps — he is driving step by step.]` });
}

// Land a HELD product (found by the pull-up gate) on the canvas and hand it over honestly: what it
// is, when it was made, where it came from — never a regenerated substitute. The sibling of
// buildReportFromHeld: that one COMPOSES from held material; this one RETRIEVES a finished product.
async function presentHeldProduct({ io, channel, sessionId, hit, alternates = [], subject }) {
  let title = '', markdown = '', ref = '';
  try {
    if (hit.kind === 'doc') {
      const row = db.getDb().prepare('SELECT id, title, body, source, created_ts FROM documents WHERE id = ?').get(hit.id);
      if (!row) throw new Error(`doc #${hit.id} vanished`);
      title = String(row.title || `Document #${row.id}`).slice(0, 90);
      markdown = String(row.body || '').slice(0, 30000);
      ref = `document #${row.id} (${row.source || 'held'})`;
    } else {
      const p = filesLib.resolvePath(hit.path);
      markdown = String(require('fs').readFileSync(p, 'utf8')).slice(0, 30000);   // no module-level fs in main.js
      title = hit.title.replace(/\.md$/i, '');
      ref = hit.path;
    }
  } catch (e) {
    console.error('[pull-up] load failed:', e.message);
    await fireToolFollowup({ io, channel, sessionId, resultText: `[You matched a held product for "${subject}" (${hit.label}) but could not load it: ${e.message}. Say so plainly and offer to rebuild — do NOT silently substitute a fresh query.]` });
    return;
  }
  const when = new Date(hit.ts).toLocaleString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
  const slug = `pullup-${String(title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'product'}`;
  try { await promiseArtifactEmit({ slug, title: title.slice(0, 60), markdown }); } catch {}
  console.log(`[pull-up] held product landed on canvas: ${hit.label} (made ${when})`);
  const altNote = alternates.length ? ` If that is not the one he means, the other matches were: ${alternates.map((a) => a.label).join(' · ')} — name them briefly.` : '';
  await fireToolFollowup({ io, channel, sessionId, resultText: `[Lucas asked you to PULL UP a product you two already made ("${subject}"). The ACTUAL artifact — ${ref}, made ${when} ET — is now on his Canvas. Tell him that in your own voice: what it is and when it was made. Do NOT present freshly-queried data as this product, and do NOT offer new research unless he asks.${altNote}]` });
}

async function buildReportFromHeld({ io, channel, sessionId, userName, topic }) {
  const t = String(topic || '').trim();
  const like = `%${t.replace(/[%_]/g, '')}%`;
  let rows = [];
  try {
    // Prefer REAL research material over chat transcripts: a "Conversation — …" doc that merely
    // mentions the topic is not evidence, and letting those fill the 8 slots starves the composer of
    // the actual dossiers (measured on Hartfield: 3 of 8 slots were transcripts of him ASKING for
    // the report). Rank research/dossier docs first, then longest — thin stubs last.
    rows = db.getDb().prepare(
      `SELECT id, title, body FROM documents
       WHERE (title LIKE ? OR body LIKE ?)
         AND COALESCE(source,'') != 'news'
         AND COALESCE(title,'') NOT LIKE 'Conversation —%'
       ORDER BY (title LIKE ?) DESC, LENGTH(COALESCE(body,'')) DESC LIMIT 8`
    ).all(like, like, like);
  } catch (e) { console.error('[report-cmd] doc query failed:', e.message); }
  if (!rows.length) {
    await fireToolFollowup({ io, channel, sessionId, resultText: `[You were asked to BUILD A REPORT on "${t}" but you hold NO research documents about it — nothing in the document store matches. Say so plainly in one or two sentences, name what you'd need to go gather, and offer to run the research. Do NOT invent a document.]` });
    return;
  }
  const material = rows.map((r) => `--- DOC #${r.id}: ${String(r.title || '').slice(0, 120)} ---\n${String(r.body || '').slice(0, 9000)}`).join('\n\n');
  console.log(`[report-cmd] composing from ${rows.length} held doc(s): ${rows.map((r) => '#' + r.id).join(', ')}`);
  const msgs = [
    { role: 'system', content: `You are composing ONE finished, professional report from research documents the assistant ALREADY HOLDS. Rules — absolute:\n• Ground ONLY in the provided documents. Never add a fact, name, number, or URL that is not in them.\n• Every source annotation already present — "(source: …)" — stays attached to its claim. Never strip one, never invent one.\n• Structure: a title line, a 2-4 sentence executive summary, then "## " sections organized by what the material actually supports, then "## Open questions" naming what the documents do NOT answer.\n• Where the documents are thin or contradict each other, SAY SO in the text rather than papering over it. An honest gap is part of the report.\nOutput Markdown only — no preamble, no "here is".` },
    { role: 'user', content: `REPORT SUBJECT: ${t}\n\nTHE DOCUMENTS YOU HOLD:\n"""\n${material.slice(0, 60000)}\n"""\n\nCompose the finished report on ${t} now.` },
  ];
  let md = '';
  try { md = await condenseComplete(msgs, { numPredict: 2600 }); } catch (e) { console.error('[report-cmd] compose call failed:', e.message); }
  if (!md || !md.trim()) {
    await fireToolFollowup({ io, channel, sessionId, resultText: `[You tried to compose the "${t}" report from ${rows.length} held document(s) but the composer returned nothing. Tell Lucas plainly that the compose step failed and the material is still there to retry — do NOT claim a document exists.]` });
    return;
  }
  md = md.trim();
  const slug = t.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'report';
  const rel = `notes/report-${slug}.md`;
  let saved = false;
  // LATENT BUG FIX (found 08-07 via lint): main.js has no module-level `fs` — this call threw
  // ReferenceError into the catch on EVERY report, so the notes/ file never actually saved
  // (the canvas copy masked it). require inline like every other main.js call site.
  try { require('fs').writeFileSync(filesLib.resolvePath(rel), `# Report — ${t}\n\n${md}\n\n---\n_Composed from ${rows.length} held research document(s): ${rows.map((r) => '#' + r.id).join(', ')}._\n`, 'utf8'); saved = true; }
  catch (e) { console.error('[report-cmd] save failed:', e.message); }
  try { await promiseArtifactEmit({ slug: `report-${slug}`, title: `Report — ${t}`.slice(0, 60), markdown: md }); } catch {}
  console.log(`[report-cmd] report on "${t}" composed (${md.length}ch) → ${saved ? rel : '(save failed)'} + canvas`);
  await fireToolFollowup({ io, channel, sessionId, resultText: `[The report Lucas asked for is BUILT and delivered — it is on his Canvas${saved ? ` and saved at ${rel}` : ''}, composed from ${rows.length} document(s) you already held (${rows.map((r) => '#' + r.id).join(', ')}). Tell him it's ready, where it is, and give the ONE most substantive finding in it — in your own voice, two or three sentences. Do not re-paste the whole report.]` });
}

async function promiseArtifactEmit({ slug, title, markdown }) {
  try {
    if (!(await ensureEngine())) return false;
    const callTool = pollCallTool();
    const tabKey = `promise-${slug}`;
    await callTool('saga_canvas_open_tab', { mode: 'DOC', tab_key: tabKey, title: String(title || 'Promised document').slice(0, 60) });
    const r = await callTool('saga_canvas_add_block', { tab_key: tabKey, block_type: 'paragraph', data: { markdown: String(markdown || '') } });
    canvasMirror(tabKey, 'DOC', String(title || 'Promised document').slice(0, 60), (r && r.block_id) || null, 'paragraph', { markdown: String(markdown || '') });
    return true;
  } catch (e) { console.error('[canvas] promise-artifact emit failed:', e.message); return false; }
}

// Live-GROW a SINGLE canvas block in place (the "building-project document" that fleshes out as work
// runs): pre-assign a stable block_id, add it once, then saga_canvas_update_block(patch) on each refresh.
// _canvasBlocks tracks the ids created this session (reset on reboot — a re-add is harmless).
const _canvasBlocks = new Set();
async function canvasUpsertBlock({ focusId, blockId, title, tabMode = 'DOC', blockType = 'paragraph', data }) {
  try {
    if (!blockId) return false;
    if (_canvasBeatGated(focusId)) return false;
    if (!(await ensureEngine())) return false;
    const ce = require('./studio/canvas_emit');
    const callTool = pollCallTool();
    const tabKey = ce.tabKeyForFocus(focusId);
    if (!_canvasTabsOpened.has(tabKey)) {
      await callTool('saga_canvas_open_tab', { mode: ce.mode(tabMode), tab_key: tabKey, title: ce.tabTitleForGoal(title) });
      _canvasTabsOpened.add(tabKey);
    }
    if (_canvasBlocks.has(blockId)) {
      await callTool('saga_canvas_update_block', { tab_key: tabKey, block_id: blockId, patch: data || {} });
    } else {
      await callTool('saga_canvas_add_block', { tab_key: tabKey, block_type: blockType, data: data || {}, block_id: blockId });
      _canvasBlocks.add(blockId);
    }
    canvasMirror(tabKey, ce.mode(tabMode), ce.tabTitleForGoal(title), blockId, blockType, data);
    return true;
  } catch (e) { console.error('[canvas] upsert failed:', e.message); return false; }
}

// CANVAS DURABILITY — the engine canvas is IN-MEMORY, so an engine/app restart WIPES a run's blocks even
// though the deliverable FILE persists. On the first tick of a run in this process, RE-EMIT its blocks from
// the durable file (covered-org sections) + the in-progress target's draft, so a restart no longer blanks
// the canvas. Idempotent block_ids match the live-grow scheme, so this refills the same blocks. Once/run.
const _canvasRehydrated = new Set();
function _secBlockId(focusId, name) { return `sec-${focusId}-${String(name || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 32)}`; }
// Emit each `## Heading` section of a deliverable body as its own idempotent canvas block (same ids the
// live-grow uses, so this REFILLS the same blocks rather than duplicating).
async function emitDeliverableSections(focusId, goal, body) {
  let n = 0;
  for (const sec of String(body || '').split(/\n(?=##\s)/)) {
    const m = sec.trim().match(/^##\s+(.+)/); if (!m) continue;
    try { await canvasUpsertBlock({ focusId, blockId: _secBlockId(focusId, m[1].trim()), title: goal, tabMode: 'RESEARCH', blockType: 'paragraph', data: { markdown: sec.trim() } }); n++; } catch {}
  }
  return n;
}
async function rehydrateCanvasFromDeliverable(focus, file, target) {
  if (!focus || _canvasRehydrated.has(focus.id)) return;
  _canvasRehydrated.add(focus.id);
  try {
    if (!(await ensureEngine())) return;
    const goal = String(focus.content || '');
    let body = ''; try { const r = filesLib.fileReadFull(file); body = (r && r.text) || ''; } catch {}
    let n = await emitDeliverableSections(focus.id, goal, body);
    if (target && target.name && target.raw) {
      const cleaned = String(target.raw).replace(/^PRIOR KNOWLEDGE[\s\S]*?(?:\n\n|$)/, '').replace(/^\s*(TARGET|FACET):.*$/gim, '').replace(/\n{3,}/g, '\n\n').trim();
      if (cleaned) { try { await canvasUpsertBlock({ focusId: focus.id, blockId: _secBlockId(focus.id, target.name), title: goal, tabMode: 'RESEARCH', blockType: 'paragraph', data: { markdown: `## ${target.name}\n\n${cleaned.slice(0, 8000)}` } }); n++; } catch {} }
    }
    if (n) console.log(`[directed] #${focus.id} canvas rehydrated after restart (${n} block(s))`);
  } catch (e) { console.error('[directed] canvas rehydrate failed:', e.message); }
}
// BOOT REPLAY — rebuild the WHOLE board from the durable mirror (lib/canvas_docs). This is the general
// restore: the file-based rehydrate below can only reconstruct her research runs from directed-*.md, so
// anything the OPERATOR dropped — a PDF, a spreadsheet, an op-ed — died with the engine's memory every
// restart. Replays with the SAME tab keys and block ids, then seeds the session sets so subsequent live-grow
// PATCHES those blocks in place instead of appending duplicates, and marks the replayed focuses as already
// rehydrated so the file sweep doesn't emit the same sections a second time.
// Legacy rows were mirrored while the drop path still built file:// URLs by concatenation, so a filename
// with a '#' (or '%', or '?') is stored broken and would replay as a blank document forever. Normalize any
// file: URL through the decode→encode pair on the way back out — a no-op for a URL that was already correct.
function repairFileUrls(data) {
  if (!data || typeof data !== 'object') return data;
  const fi = require('./lib/file_ingest');
  let out = data;
  for (const k of ['src', 'file', 'url', 'href']) {
    const v = out[k];
    if (typeof v !== 'string' || !/^file:/i.test(v)) continue;
    const fixed = fi.pathToSrc(fi.srcToPath(v));
    if (fixed !== v) { if (out === data) out = { ...data }; out[k] = fixed; }
  }
  return out;
}

async function replayCanvasFromStore() {
  try {
    if (!(await ensureEngine())) return 0;
    const store = require('./lib/canvas_docs');
    let docs = []; try { docs = store.all(); } catch (e) { console.error('[canvas] replay read failed:', e.message); return 0; }
    if (!docs.length) return 0;
    const callTool = pollCallTool();
    let tabs = 0, blocks = 0;
    for (const d of docs) {
      if (!d.blocks.length) continue;                 // an empty shell isn't worth a tab
      try {
        await callTool('saga_canvas_open_tab', { mode: d.mode || 'DOC', tab_key: d.tabKey, title: d.title || '' });
        _canvasTabsOpened.add(d.tabKey);
        tabs++;
        for (const b of d.blocks) {
          await callTool('saga_canvas_add_block', { tab_key: d.tabKey, block_type: b.blockType, data: repairFileUrls(b.data) || {}, block_id: b.blockId });
          _canvasBlocks.add(b.blockId);
          blocks++;
        }
        const focusId = Number((String(d.tabKey).match(/^directed-(\d+)$/) || [])[1]);
        if (focusId) _canvasRehydrated.add(focusId);   // the store already restored it — don't re-emit from file
      } catch (e) { console.error(`[canvas] replay of "${d.tabKey}" failed:`, e.message); }
    }
    try { store.prune(); } catch (e) {}
    // Sweep layout rows for documents that no longer exist. The board is now fully restored, so the set of
    // real documents is exactly (mirror ∪ whatever else the engine is holding) — anything else in the layout
    // table is a ghost of a document lost to an old restart.
    try {
      const live = new Set(docs.map((d) => d.tabKey));
      const snap = await canvasSnapshot();
      for (const t of ((snap && Array.isArray(snap.tabs)) ? snap.tabs : [])) { const k = t.tab_key || t.key; if (k) live.add(k); }
      const swept = canvasLayoutStore.clearMissing([...live]);
      if (swept) console.log(`[canvas] swept ${swept} layout row(s) for documents that no longer exist`);
    } catch (e) { console.error('[canvas] layout sweep failed:', e.message); }
    if (tabs) console.log(`[canvas] replayed ${tabs} document(s) / ${blocks} block(s) from the durable store`);
    return tabs;
  } catch (e) { console.error('[canvas] replay failed:', e.message); return 0; }
}

// BOOT durability — re-emit recent COMPLETED deliverables to the canvas after a restart (an active run
// self-rehydrates on its next tick, but a finished run has no tick, so its blocks would stay wiped).
async function rehydrateRecentCanvasDeliverables(limit = 6) {
  try {
    if (!(await ensureEngine())) return;
    const fsx = require('fs'); const p = require('path');
    const dir = p.join(__dirname, 'data', 'zoe_workspace', 'notes');
    let files = [];
    try { files = fsx.readdirSync(dir).filter(f => /^directed-\d+\.md$/.test(f)).map(f => ({ f, m: fsx.statSync(p.join(dir, f)).mtimeMs })).sort((a, b) => b.m - a.m).slice(0, limit); } catch { return; }
    for (const { f } of files) {
      const id = Number((f.match(/directed-(\d+)\.md/) || [])[1]); if (!id || _canvasRehydrated.has(id)) continue;
      let body = ''; try { body = fsx.readFileSync(p.join(dir, f), 'utf8'); } catch {}
      if (!body || body.length < 40) continue;
      const goal = ((body.match(/\*\*Task:\*\*\s*(.+)/) || [])[1] || 'Directed research').trim();
      _canvasRehydrated.add(id);
      await emitDeliverableSections(id, goal, body);
    }
    if (files.length) console.log(`[canvas] re-emitted ${files.length} recent deliverable(s) on boot`);
  } catch (e) { console.error('[canvas] boot rehydrate failed:', e.message); }
}

// SCRIBE HEARTBEAT (the meeting-scribe LANE on its OWN cadence — handoff item 1). While a canvas meeting
// is live, tick the scribe (own model) + LIVE-GROW the notes on the canvas (the building-project document
// fleshing out as the meeting runs). When the meeting ends (gmeet stage done/none), finalize → land the
// completed notes + companion transcript into the short-term store (meeting_lane) → emit the final doc →
// stop. Truly parallel to her actor (gmeet), never serialized with the idle tick.
let scribeTimer = null;
const SCRIBE_TICK_MS = 20 * 1000;
function startScribeHeartbeat() {
  if (scribeTimer) return;
  scribeTimer = setInterval(() => { scribeHeartbeatTick().catch(() => {}); }, SCRIBE_TICK_MS);
  setTimeout(() => { scribeHeartbeatTick().catch(() => {}); }, 4000);
  console.log('[scribe] heartbeat started (own cadence, every 20s)');
}
function stopScribeHeartbeat() {
  if (scribeTimer) { clearInterval(scribeTimer); scribeTimer = null; console.log('[scribe] heartbeat stopped'); }
}
async function emitMeetingNotes(content, { final = false } = {}) {
  const text = String(content || '').trim();
  if (!text) return;
  const startedAt = parseInt(db.getMeta('gmeet_started_at') || '0', 10) || 0;
  const title = require('./lib/meeting_lane').meetingTitle({ url: db.getMeta('gmeet_url') || '' });
  const md = `# ${title}${final ? ' (final)' : ' — live'}\n\n${text}`;
  await canvasUpsertBlock({ focusId: `meeting-${startedAt}`, blockId: `meetnotes-${startedAt}`, title, tabMode: 'DOC', blockType: 'paragraph', data: { markdown: md } });
}
async function scribeHeartbeatTick() {
  const scribe = require('./lib/meeting_scribe');
  const gmeet = require('./lib/gmeet');
  if (gmeet.active()) {
    let r = null; try { r = await scribe.tick(); } catch (e) { console.error('[scribe] tick failed:', e.message); }
    if (r && r.updated) { try { await emitMeetingNotes(scribe.minutes(), { final: false }); } catch {} }
    // MEETING CARDS (Slice B): surface a card for every person / place / event NAMED in the fresh transcript
    // (our own cursor, independent of the scribe's) — "in a meeting with Russ and Traci, their cards pop up".
    try {
      const cur = parseInt(db.getMeta('cards_cursor') || db.getMeta('gmeet_started_at') || '0', 10) || 0;
      const rows = db.getTranscriptSince(cur, 400) || [];
      if (rows.length) {
        const fresh = rows.map(t => `${t.speaker ? t.speaker + ': ' : ''}${t.text}`).join('\n');
        db.setMeta('cards_cursor', String(rows[rows.length - 1].ts + 1));
        surfaceMeetingMentions(fresh).catch(() => {});
      }
    } catch (e) {}
    return;
  }
  // meeting ended — finalize + land + final canvas emit (once), then stop the lane
  if (scribe.hasPending()) {
    // Read the minutes AFTER finalize: that is where the authoritative digest is written (one pass
    // over the whole raw transcript on the big model). Reading them first — as this did — captured
    // only the live running view, which is precisely the degraded artefact being replaced.
    const _liveMinutes = (() => { try { return scribe.minutes(); } catch { return ''; } })();
    let recap = ''; try { recap = await scribe.finalize(); } catch (e) { console.error('[scribe] finalize failed:', e.message); }
    const minutes = (() => { try { return scribe.lastMinutes() || _liveMinutes; } catch { return _liveMinutes; } })();
    if (recap) { try { const rr = db.insertMonologue({ content: `Meeting record (scribe):\n${recap}`, model: 'scribe', type: 'reading' }); if (mainWindow && !mainWindow.isDestroyed()) mainWindow.webContents.send('monologue:tick', { id: rr.id, ts: rr.ts, content: '(scribe) meeting record', type: 'reading' }); } catch {} }
    // Stop the Echo meeting-audio capture (if it was running) → its diarized transcript becomes the
    // authoritative companion (else the caption transcript stands in). Fail-safe.
    let audioTranscript = '';
    try { const a = await require('./lib/meeting_audio').stop({ dispatch: (t) => echoSuit.dispatch(t) }); if (a && a.ok && a.transcript) { audioTranscript = a.transcript; console.log(`[meet-audio] diarized transcript: ${a.segments.length} segments`); } } catch (e) { console.error('[meet-audio] stop failed:', e.message); }
    let _notesId = null;
    try { const ml = require('./lib/meeting_lane').land({ minutes, recap, audioTranscript }); if (ml.landed) { _notesId = ml.notesId; console.log(`[meeting] notes${ml.hasTranscript ? ` + companion transcript (${audioTranscript ? 'audio' : 'captions'})` : ''} landed in short-term store (doc ${ml.notesId}${ml.transcriptId ? `, transcript ${ml.transcriptId}` : ''})`); } } catch (e) { console.error('[meeting] landing failed:', e.message); }
    // CLOUD-LEVERAGE (meeting → OBJECT GRAPH): decompose the meeting record through the SAME machine a canvas
    // doc-drop uses — attendees + named orgs + relations become real Echo objects/cards (net-new people flow
    // toward the Puller), not just a flat memory item. The audio transcript (if any) is the richest source.
    // Fire-and-forget + fail-soft: never delays or breaks finalize.
    try {
      const body = [recap, minutes, audioTranscript].filter(Boolean).join('\n\n');
      if (body.trim().length >= 40) {
        const mtitle = (() => { try { return require('./lib/meeting_lane').meetingTitle({ url: db.getMeta('gmeet_url') || '' }); } catch { return 'Meeting'; } })();
        const mid = _notesId != null ? `meeting:${_notesId}` : `meeting:${db.getMeta('gmeet_started_at') || 'session'}`;
        decomposeLandedDoc({ id: mid, title: `Meeting — ${mtitle}`, body, source: 'meeting' }).catch((e) => console.error('[meeting] decompose failed:', e && e.message));
      }
    } catch (e) { console.error('[meeting] decompose wiring failed:', e && e.message); }
    // ATTENDANCE → the encounter log (W4). Who was in the room is something Zoe OBSERVED — she captured
    // the captions live and the name is Meet's own speaker badge. That is evidence, and it is a
    // different kind of thing from what anyone SAID, which reaches the graph through the decompose above
    // marked `stated`. Fail-soft: never delays or breaks finalize.
    try {
      const _code = db.getMeta('gmeet_code') || (db.getMeta('gmeet_url') || '').split('/').pop() || null;
      if (_code) {
        const _lines = db.getTranscriptForMeeting(_code);
        const _me = require('./lib/meeting_encounters');
        const _st = _me.attendanceStats(_lines);
        const _res = require('./lib/encounters').recordMany(_me.attendanceEncounters(_lines));
        console.log(`[meeting] attendance → ${_res.added} encounter(s) for ${_st.people} person(s); ${_st.unnamed} of ${_st.lines} line(s) had no speaker`);
      }
    } catch (e) { console.error('[meeting] attendance log failed:', e && e.message); }
    // FINAL VIEW = the full notes (recap header + the rich running minutes), matching the landed doc. Emitting
    // the recap ALONE dropped the detailed Topics/Decisions the operator watched accrue ("notes ate themselves").
    // HER ACTION LEDGER — what she looked up, what she connected, and what she wanted to say in the
    // room but held back. This is the review surface: until the meeting chat is opened
    // (ZOE_MEET_CHAT=on) her proposed contributions exist ONLY here, and they are the thing to read
    // before trusting her to post them live.
    let _ledger = '';
    try { _ledger = require('./lib/gmeet').renderLedger(require('./lib/gmeet').ledgerRows()); } catch (e) { console.error('[meeting] ledger render failed:', e && e.message); }
    if (_ledger) console.log(`[meeting] action ledger → ${require('./lib/gmeet').ledgerRows().length} entr(ies), ${require('./lib/gmeet').ledgerRows().filter((r) => r.withheld).length} withheld`);
    const finalBody = [
      recap,
      (minutes && minutes.trim()) ? `## Running minutes\n${minutes}` : '',
      _ledger ? `## What I did in this meeting\n${_ledger}` : '',
    ].filter(Boolean).join('\n\n') || recap || minutes;
    try { await emitMeetingNotes(finalBody, { final: true }); } catch {}
  }
  stopScribeHeartbeat();
}

